# Fechas típicas de un periodo AAAA-N cuando todavía no tiene sesiones de donde tomarlas:
# 1 = semestre de primavera, 2 = de otoño, 3 = verano.
FECHAS_TIPICAS = {
    '1': ((1, 26), (6, 12)),
    '2': ((8, 17), (12, 11)),
    '3': ((6, 15), (7, 31)),
}


def _fechas_por_defecto(clave):
    coincide = re.match(r'^(\d{4})-(\d)$', clave)
    if coincide and coincide.group(2) in FECHAS_TIPICAS:
        anio = int(coincide.group(1))
        (mes_i, dia_i), (mes_f, dia_f) = FECHAS_TIPICAS[coincide.group(2)]
        return date(anio, mes_i, dia_i), date(anio, mes_f, dia_f)
    hoy = date.today()
    return hoy, hoy + timedelta(days=120)


def copiar_periodos_de_los_grupos(apps, schema_editor):
    """Crea una fila de `periodo` por cada periodo que ya usan los grupos (RF-17).

    Las fechas salen de las sesiones del periodo; si no tiene, de las fechas
    típicas. Queda activo solo el periodo más reciente (el de mayor clave, que
    se ordena como texto AAAA-N): los anteriores quedan inactivos.
    """
    Grupo = apps.get_model('asistencia', 'Grupo')
    Sesion = apps.get_model('asistencia', 'Sesion')
    Periodo = apps.get_model('asistencia', 'Periodo')

    for clave in sorted(set(Grupo.objects.values_list('periodo', flat=True))):
        rango = Sesion.objects.filter(grupo__periodo=clave).aggregate(
            primera=Min('fecha'), ultima=Max('fecha'))
        inicio, fin = rango['primera'], rango['ultima']
        if inicio is None or fin is None or fin <= inicio:
            inicio, fin = _fechas_por_defecto(clave)
        Periodo.objects.create(clave=clave, fecha_inicio=inicio, fecha_fin=fin, activo=False)

    reciente = Periodo.objects.order_by('-clave').first()
    if reciente is not None:
        reciente.activo = True
        reciente.save(update_fields=['activo'])


